package formula

import (
	"sort"
	"strings"
)

// Function is what the xlsx corpus shows of one function, from
// Excel-authored workbooks only (docProps/app.xml names Microsoft Excel).
// The table is generated by TestCorpusFunctionTable; a function the
// corpus does not hold is absent, never guessed.
type Function struct {
	// Name is the function's name without prefix, in upper case.
	Name string
	// Prefix is the stored prefix Excel wrote ("", PrefixFuture or
	// PrefixWorksheet).
	Prefix string
	// Seen is where it was first seen with that prefix: corpus-relative
	// file, part and cell or name.
	Seen string
	// Count is how many formulas use it with that prefix.
	Count int
	// Also lists other prefixes the corpus wrote it with, and how often,
	// as "prefix=count" (unprefixed is "-"); empty when there are none.
	Also string
	// Spill is where the corpus shows it spilling on its own: the root
	// call of a multi-cell dynamic-array formula (a cell with cell
	// metadata, t="array") whose arguments hold only constants and
	// single cells, so the spill can only come from the function.
	// Empty when the corpus has no such formula.
	Spill string
}

// LookupFunction returns what the corpus shows of the function named
// name (with or without its stored prefix, ignoring case), and else what
// Microsoft's future-function list says of it (futureFunctions: Prefix
// only, Seen "microsoft-future-functions", no Spill evidence).
func LookupFunction(name string) (Function, bool) {
	_, base := SplitPrefix(name)
	base = strings.ToUpper(base)
	i := sort.Search(len(functionTable), func(i int) bool { return functionTable[i].Name >= base })
	if i < len(functionTable) && functionTable[i].Name == base {
		return functionTable[i], true
	}
	for _, f := range futureFunctions {
		if f.name == base {
			return Function{Name: base, Prefix: f.prefix, Seen: "microsoft-future-functions"}, true
		}
	}
	return Function{}, false
}

// IsDynamicArray reports whether the function spills on its own: the
// corpus shows it spilling (Function.Spill), or it is one of Excel's
// array-returning functions in spillFunctions. false means no such
// evidence, not that it never spills (an array expression such as
// A1:A3*2 also spills; callers that must refuse every spill check more
// than names).
func IsDynamicArray(name string) bool {
	f, ok := LookupFunction(name)
	if ok && f.Spill != "" {
		return true
	}
	_, base := SplitPrefix(name)
	return spillFunctions[strings.ToUpper(base)]
}

// spillFunctions are the functions that return an array and so spill in
// Excel 365: the dynamic-array functions Microsoft introduced with spilled
// arrays (FILTER, RANDARRAY, SEQUENCE, SORT, SORTBY, UNIQUE), the later
// array-shaping and LAMBDA helpers (TEXTSPLIT, VSTACK, HSTACK, TOROW,
// TOCOL, WRAPROWS, WRAPCOLS, TAKE, DROP, EXPAND, CHOOSEROWS, CHOOSECOLS,
// MAKEARRAY, MAP, SCAN, BYROW, BYCOL), and the older array-returning
// functions that
// spill when entered in Excel 365 (TRANSPOSE, MMULT, MINVERSE, MUNIT,
// FREQUENCY, LINEST, LOGEST, TREND, GROWTH). XLOOKUP and XMATCH are left
// out: they spill only for some arguments and usually return one value,
// so refusing them by name would refuse common formulas. Compiled 2026-11-14 from
// Microsoft's function reference by the coordinator, not from a fetched
// list; the corpus table (Function.Spill) adds any it shows spilling.
var spillFunctions = map[string]bool{
	"FILTER": true, "RANDARRAY": true, "SEQUENCE": true, "SORT": true, "SORTBY": true, "UNIQUE": true,
	"TEXTSPLIT": true, "VSTACK": true, "HSTACK": true, "TOROW": true, "TOCOL": true,
	"WRAPROWS": true, "WRAPCOLS": true, "TAKE": true, "DROP": true, "EXPAND": true,
	"CHOOSEROWS": true, "CHOOSECOLS": true, "MAKEARRAY": true, "MAP": true, "SCAN": true,
	"BYROW": true, "BYCOL": true,
	"TRANSPOSE": true, "MMULT": true, "MINVERSE": true, "MUNIT": true, "FREQUENCY": true,
	"LINEST": true, "LOGEST": true, "TREND": true, "GROWTH": true,
}
